class Solution {
public:
    int numberOfSubarrays(vector<int>& nums, int k) {
        vector<int> seen(nums.size() + 1, 0);
        seen[0] = 1;
        int odd = 0, count = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            odd += nums[i] % 2;
            if (odd >= k) count += seen[odd - k];
            seen[odd]++;
        }
        return count;
    }
};
